import{_ as p,a0 as l,w as o,s as d,ao as r,I as t,x as a,a1 as e,A as n}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const C=JSON.parse('{"title":"Python 3.9 如何修復裝飾器並改進字典 | LCTT x X-CMD","titleTemplate":false,"description":"Python 3.9 如何修復裝飾器並改進字典 | LCTT (202106) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Python 3.9 如何修復裝飾器並改進字典 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Python 3.9 如何修復裝飾器並改進字典 | LCTT (202106) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202106/20210521 How Python 3.9 fixed decorators and improved dictionaries","title":"Python 3.9 如何修復裝飾器並改進字典","tag":"202106","desc":""},"relativePath":"202106/20210521 How Python 3.9 fixed decorators and improved dictionaries.md","filePath":"[post].md"}'),h={name:"202106/20210521 How Python 3.9 fixed decorators and improved dictionaries.md"};function c(g,s,u,k,b,f){const i=l("Link");return o(),d("div",null,[s[15]||(s[15]=r(`<h1 id="python-3-9-如何修復裝飾器並改進字典" tabindex="-1">Python 3.9 如何修復裝飾器並改進字典 <a class="header-anchor" href="#python-3-9-如何修復裝飾器並改進字典" aria-label="Permalink to “Python 3.9 如何修復裝飾器並改進字典”">​</a></h1><blockquote><p>探索最近版本的 Python 的一些有用的特性。</p></blockquote><p><img src="https://img.linux.net.cn/data/attachment/album/202106/12/115315xrnd4evse8uzpi8i.jpg" alt=""></p><p>這是 Python 3.x 首發特性系列文章中的第十篇，其中一些版本已經發布了一段時間。Python 3.9 在 2020 年首次發佈，具有很酷的新特性，但仍未被充分利用。下面是其中的三個。</p><h3 id="添加字典" tabindex="-1">添加字典 <a class="header-anchor" href="#添加字典" aria-label="Permalink to “添加字典”">​</a></h3><p>假設你有一個 <code>defaults</code> 字典，而你想更新它的參數。在 Python 3.9 之前，最好的辦法是複製 <code>defaults</code> 字典，然後使用 <code>.update()</code> 方法。</p><p>Python 3.9 為字典引入了聯合運算符：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>defaults = dict(who=&quot;someone&quot;, where=&quot;somewhere&quot;)</span></span>
<span class="line"><span>params = dict(where=&quot;our town&quot;, when=&quot;today&quot;)</span></span>
<span class="line"><span>defaults | params</span></span></code></pre></div><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>    {&#39;who&#39;: &#39;someone&#39;, &#39;where&#39;: &#39;our town&#39;, &#39;when&#39;: &#39;today&#39;}</span></span></code></pre></div><p>注意，順序很重要。在這種情況下，正如預期，來自 <code>params</code> 的 <code>where</code> 值覆蓋了默認值。</p><h3 id="刪除前綴" tabindex="-1">刪除前綴 <a class="header-anchor" href="#刪除前綴" aria-label="Permalink to “刪除前綴”">​</a></h3><p>如果你用 Python 做臨時的文本解析或清理，你會寫出這樣的代碼：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>def process_pricing_line(line):</span></span>
<span class="line"><span>    if line.startswith(&quot;pricing:&quot;):</span></span>
<span class="line"><span>        return line[len(&quot;pricing:&quot;):]</span></span>
<span class="line"><span>    return line</span></span>
<span class="line"><span>process_pricing_line(&quot;pricing:20&quot;)</span></span></code></pre></div><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>    &#39;20&#39;</span></span></code></pre></div><p>這樣的代碼很容易出錯。例如，如果字符串被錯誤地複製到下一行，價格就會變成 <code>0</code> 而不是 <code>20</code>，而且會悄悄地發生。</p><p>從 Python 3.9 開始，字符串有了一個 <code>.lstrip()</code> 方法：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>&quot;pricing:20&quot;.lstrip(&quot;pricing:&quot;)</span></span></code></pre></div><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>    &#39;20&#39;</span></span></code></pre></div><h3 id="任意的裝飾器表達式" tabindex="-1">任意的裝飾器表達式 <a class="header-anchor" href="#任意的裝飾器表達式" aria-label="Permalink to “任意的裝飾器表達式”">​</a></h3><p>以前，關於裝飾器中允許哪些表達式的規則沒有得到充分的説明，而且很難理解。例如：雖然</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>@item.thing</span></span>
<span class="line"><span>def foo():</span></span>
<span class="line"><span>    pass</span></span></code></pre></div><p>是有效的，而且：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>@item.thing()</span></span>
<span class="line"><span>def foo():</span></span>
<span class="line"><span>    pass</span></span></code></pre></div><p>是有效的，相似地：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>@item().thing</span></span>
<span class="line"><span>def foo():</span></span>
<span class="line"><span>    pass</span></span></code></pre></div><p>產生一個語法錯誤。</p><p>從 Python 3.9 開始，任何表達式作為裝飾器都是有效的：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>from unittest import mock</span></span>
<span class="line"><span></span></span>
<span class="line"><span>item = mock.MagicMock()</span></span>
<span class="line"><span></span></span>
<span class="line"><span>@item().thing</span></span>
<span class="line"><span>def foo():</span></span>
<span class="line"><span>    pass</span></span>
<span class="line"><span>print(item.return_value.thing.call_args[0][0])</span></span></code></pre></div><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>    &lt;function foo at 0x7f3733897040&gt;</span></span></code></pre></div><p>雖然在裝飾器中保持簡單的表達式仍然是一個好主意，但現在是人類的決定，而不是 Python 分析器的選擇。</p><h3 id="歡迎來到-2020-年" tabindex="-1">歡迎來到 2020 年 <a class="header-anchor" href="#歡迎來到-2020-年" aria-label="Permalink to “歡迎來到 2020 年”">​</a></h3><p>Python 3.9 大約在一年前發佈，但在這個版本中首次出現的一些特性非常酷，而且沒有得到充分利用。如果你還沒使用，那麼將它們添加到你的工具箱中。</p><hr>`,33)),t("p",null,[s[1]||(s[1]=a("via: ",-1)),e(i,{href:"https://opensource.com/article/21/5/python-39-features"},{default:n(()=>[...s[0]||(s[0]=[a("https://opensource.com/article/21/5/python-39-features",-1)])]),_:1})]),t("p",null,[s[6]||(s[6]=a("作者：",-1)),e(i,{href:"https://opensource.com/users/moshez"},{default:n(()=>[...s[2]||(s[2]=[a("Moshe Zadka",-1)])]),_:1}),s[7]||(s[7]=a(" 選題：",-1)),e(i,{href:"https://github.com/lujun9972"},{default:n(()=>[...s[3]||(s[3]=[a("lujun9972",-1)])]),_:1}),s[8]||(s[8]=a(" 譯者：",-1)),e(i,{href:"https://github.com/geekpi"},{default:n(()=>[...s[4]||(s[4]=[a("geekpi",-1)])]),_:1}),s[9]||(s[9]=a(" 校對：",-1)),e(i,{href:"https://github.com/wxy"},{default:n(()=>[...s[5]||(s[5]=[a("wxy",-1)])]),_:1})]),t("p",null,[s[12]||(s[12]=a("本文由 ",-1)),e(i,{href:"https://github.com/LCTT/TranslateProject"},{default:n(()=>[...s[10]||(s[10]=[a("LCTT",-1)])]),_:1}),s[13]||(s[13]=a(" 原創編譯，",-1)),e(i,{href:"https://linux.cn/"},{default:n(()=>[...s[11]||(s[11]=[a("Linux中國",-1)])]),_:1}),s[14]||(s[14]=a(" 榮譽推出",-1))])])}const x=p(h,[["render",c]]);export{C as __pageData,x as default};
